def smallest_fixed_point(arr):
 low,high=0,len(arr)-1;answer=-1
 while low<=high:
  middle=(low+high)//2
  if arr[middle]>=middle:
   if arr[middle]==middle:answer=middle
   high=middle-1
  else:low=middle+1
 return answer

